class Invoice
    private define product1 as Product;
    private define product2 as Product;

    method constructor(aPrice1 as integer, aPrice2 as integer)
        this.product1 <- new Product(aPrice1);
        this.product2 <- new Product(aPrice2);
    endMethod

    public method Total() as integer
        return this.product1.Price() + this.product2.Price();
    endMethod
endClass

